 /* ViaFlow shared UI language: keep role and module pages visually aligned. */
 :where(.dashboard-card, .panel-card, .announcement-card, .card, .auth-card, .dash-kpi) {
 border: 1px solid var(--wb-border);
 border-radius: 1rem;
