 }

 /* Bootstrap backdrops stay below the dialog, including stacked confirmations. */
 .modal-backdrop {
 background-color: rgba(6, 43, 128, 0.42);
 -webkit-backdrop-filter: blur(5px);
 backdrop-filter: blur(5px);
 }

 .modal-backdrop.fade {
 transition: opacity 0.25s ease;
 }

